{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello MD जी आपको कौन सा product चाहिए please details बता दीजिए।"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "ये मेरे को चाहिए बारह volt दस ampere।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आपको जो बारह V दस A वाला power adapter या battery charger चाहिए वही product चाहिए ना?"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "generator charger."
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "आपको जो generator के लिए charger चाहिए वही products चाहिए ना?"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "photo डाले हैं WhatsApp पे।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "photo आप seller को directly share कर दीजिएगा।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "अभी मेरे पास photo देखने की facility नहीं है।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "के लिए।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "आपको जो generator के लिए charger चाहिए वही product चाहिए ना?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "हाँ हाँ।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए?"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "हम दो piece लेंगे।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "चलिए अब output voltage के बारे में बात कर लेते हैं।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए 12 V या कुछ और?"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "बारह जी।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "अब charging current में क्या prefer करेंगे 10 A, 20 A या कोई और?"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "दा पे।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
